401	            <p className="text-xs text-red-500">{errors.protocolo.message}</p>
402	          )}
403	        </div>
404	
405	        <div className="flex flex-col gap-1.5">
406	          <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
407	            Senha
408	          </Label>
409	          <div className="relative">
410	            <Input
411	              data-mia-skip
412	              {...register('senha')}
413	              type={mostrarSenha ? 'text' : 'password'}
414	              placeholder="Sua senha de acompanhamento"
415	              className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl h-11 pr-10"
416	            />
417	            <button
418	              type="button"
419	              data-mia-skip
420	              onClick={() => setMostrarSenha((v) => !v)}
421	              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-[#57715B] transition-colors"
422	              aria-label={mostrarSenha ? 'Ocultar senha' : 'Mostrar senha'}
423	            >
424	              {mostrarSenha ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
425	            </button>
426	          </div>
427	          {errors.senha && (
428	            <p className="text-xs text-red-500">{errors.senha.message}</p>
429	          )}
430	        </div>
431	
432	        <Button
433	          type="submit"
434	          disabled={consultarProtocolo.isPending}
435	          className="w-full bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-11 gap-2"
436	        >
437	          {consultarProtocolo.isPending ? (
438	            <Loader2 className="h-4 w-4 animate-spin" />
439	          ) : null}
440	          {consultarProtocolo.isPending ? 'Consultando...' : 'Consultar protocolo'}
441	        </Button>
442	      </form>
443	
444	      {/* Resultado */}
445	      {resultado !== null && !resultado.ok && (
446	        <div className="rounded-2xl border border-red-200 dark:border-red-800/30 bg-red-50 dark:bg-red-900/10 p-4 text-sm text-red-600 dark:text-red-400">
447	          Protocolo ou senha incorretos.
448	        </div>
449	      )}
450	
451	      {resultado !== null && resultado.ok && (
452	        <div className="flex flex-col gap-4">
453	          {/* Cabeçalho da denúncia */}
454	          <GlassCard className="p-4 flex flex-col gap-3">
455	            <div className="flex flex-wrap items-center gap-2">
456	              <span className="font-mono text-sm font-bold text-[#57715B]">
457	                {resultado.denuncia.protocolo}
458	              </span>
459	              <CategoriaBadge categoria={resultado.denuncia.categoria} />
460	              <StatusBadge status={resultado.denuncia.status} />
461	            </div>
462	            <p className="text-xs text-muted-foreground">
463	              Registrada em{' '}
464	              {format(parseISO(resultado.denuncia.created_at), "dd/MM/yyyy 'às' HH:mm", {
465	                locale: ptBR,
466	              })}
467	            </p>
468	            <div className="border-t border-[#57715B]/10 pt-3">
469	              <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">
470	                Mensagem original
471	              </p>
472	              <p className="text-sm text-[#2D362E] dark:text-[#E6DCCF] whitespace-pre-wrap">
473	                {resultado.denuncia.mensagem}
474	              </p>
475	            </div>
476	          </GlassCard>
477	
478	          {/* Thread de mensagens */}
479	          {resultado.mensagens.length > 0 && (
480	            <div className="flex flex-col gap-3 py-2">
481	              <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
482	                Conversas
483	              </p>
484	              <div className="flex flex-col gap-3">
485	                {resultado.mensagens.map((msg, i) => (
486	                  <MensagemBubble key={i} mensagem={msg} />
487	                ))}
488	              </div>
489	            </div>
490	          )}
491	
492	          {/* Responder */}
493	          {resultado.denuncia.status !== 'resolvida' &&
494	            resultado.denuncia.status !== 'arquivada' && (
495	              <div className="flex flex-col gap-2">
496	                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
497	                  Adicionar mensagem
498	                </p>
499	                <textarea
500	                  data-mia-skip
501	                  value={respostaTexto}
502	                  onChange={(e) => setRespostaTexto(e.target.value)}
503	                  rows={3}
504	                  placeholder="Adicione informações ou acompanhe o andamento..."
505	                  className="w-full resize-none rounded-xl bg-white/60 dark:bg-black/20 backdrop-blur-md border border-[#57715B]/15 px-3 py-2.5 text-sm text-[#2D362E] dark:text-[#E6DCCF] placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#57715B]/30 transition-shadow"
506	                />
507	                <Button
508	                  type="button"
509	                  data-mia-skip
510	                  onClick={onResponder}
511	                  disabled={!respostaTexto.trim() || responderProtocolo.isPending}
512	                  className="self-end bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-9 px-4 gap-2 text-sm"
513	                >
514	                  {responderProtocolo.isPending ? (
515	                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
516	                  ) : (
517	                    <Send className="h-3.5 w-3.5" />
518	                  )}
519	                  Enviar
520	                </Button>
521	              </div>
522	            )}
523	        </div>
524	      )}
525	    </div>
526	  );
527	}
528	
529	// ---------------------------------------------------------------------------
530	// Página principal
531	// ---------------------------------------------------------------------------
532	
