/**
 * Canal anônimo de denúncias — página pública, sem login, sem DashboardLayout.
 * Duas abas: "Fazer denúncia" e "Acompanhar".
 */

import { useState, useRef } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { toast } from 'sonner';
import { Shield, Lock, Copy, CheckCircle, ChevronRight, Send, Loader2, Eye, EyeOff } from 'lucide-react';
import { format, parseISO } from 'date-fns';
import { ptBR } from 'date-fns/locale';

import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/shared/ui/tabs';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import { GlassCard } from '@/shared/ui/glass-card';
import { MommaPageLayout } from '@/shared/ui/MommaPageLayout';

import { CATEGORIAS_OUVIDORIA, labelCategoria, labelStatus } from '../lib/categorias';
import { LOJAS_OUVIDORIA } from '../lib/lojas';
import { useEnviarDenuncia } from '../model/useEnviarDenuncia';
import { useConsultarProtocolo } from '../model/useConsultarProtocolo';
import { useResponderProtocolo } from '../model/useResponderProtocolo';
import { MensagemBubble } from './MensagemBubble';
import { CategoriaBadge } from './CategoriaBadge';
import { StatusBadge } from './StatusBadge';
import type { CategoriaOuvidoria, ConsultaProtocoloResult, MensagemThread } from '../types';

// ---------------------------------------------------------------------------
// Schema de denúncia
// ---------------------------------------------------------------------------

const denunciaSchema = z.object({
  categoria: z.string({ required_error: 'Selecione uma categoria' }).min(1, 'Selecione uma categoria') as z.ZodType<CategoriaOuvidoria>,
  loja_id: z.string().optional(),
  mensagem: z
    .string({ required_error: 'Escreva sua mensagem' })
    .min(10, 'Mínimo de 10 caracteres')
    .max(5000, 'Máximo de 5.000 caracteres'),
  senha: z.string({ required_error: 'Crie uma senha de acompanhamento' }).min(4, 'Mínimo de 4 caracteres'),
  // Honeypot — nunca deve ser preenchido por humanos
  hp_field: z.string().optional(),
});

type DenunciaFormValues = z.infer<typeof denunciaSchema>;

// Schema de consulta de protocolo
const consultaSchema = z.object({
  protocolo: z.string({ required_error: 'Informe o protocolo' }).min(1, 'Informe o protocolo'),
  senha: z.string({ required_error: 'Informe a senha' }).min(1, 'Informe a senha'),
});

type ConsultaFormValues = z.infer<typeof consultaSchema>;

// ---------------------------------------------------------------------------
// Sub-componente: Formulário de denúncia
// ---------------------------------------------------------------------------

interface FormDenunciaProps {
  onSuccess: (protocolo: string) => void;
  onAcompanhar: (protocolo: string) => void;
}

function FormDenuncia({ onSuccess, onAcompanhar }: FormDenunciaProps) {
  const [protocolo, setProtocolo] = useState<string | null>(null);
  const [copiado, setCopiado] = useState(false);
  const [mostrarSenha, setMostrarSenha] = useState(false);
  const enviarDenuncia = useEnviarDenuncia();

  const {
    register,
    handleSubmit,
    watch,
    setValue,
    formState: { errors },
    reset,
  } = useForm<DenunciaFormValues>({
    resolver: zodResolver(denunciaSchema),
    defaultValues: { hp_field: '' },
  });

  const mensagemValue = watch('mensagem') ?? '';

  const onSubmit = handleSubmit(async (values) => {
    // Honeypot: se preenchido, fingir sucesso sem enviar
    if (values.hp_field) {
      setProtocolo('XXX-FAKE-0000');
      return;
    }

    try {
      const lojaId = values.loja_id && values.loja_id !== '__nao_informar'
        ? parseInt(values.loja_id, 10)
        : null;

      const proto = await enviarDenuncia.mutateAsync({
        categoria: values.categoria,
        loja_id: lojaId,
        mensagem: values.mensagem,
        senha: values.senha,
      });

      setProtocolo(proto);
      onSuccess(proto);
      reset();
    } catch (err) {
      toast.error((err as Error).message ?? 'Erro ao registrar denúncia');
    }
  });

  const copiarProtocolo = async () => {
    if (!protocolo) return;
    try {
      await navigator.clipboard.writeText(protocolo);
      setCopiado(true);
      setTimeout(() => setCopiado(false), 2000);
    } catch {
      toast.error('Não foi possível copiar. Anote manualmente.');
    }
  };

  if (protocolo) {
    return (
      <div className="flex flex-col gap-6">
        {/* Sucesso */}
        <div className="flex flex-col items-center gap-4 py-6">
          <div className="rounded-full bg-emerald-50 dark:bg-emerald-900/20 p-4">
            <CheckCircle className="h-8 w-8 text-emerald-600" />
          </div>
          <div className="text-center">
            <p className="text-lg font-semibold text-[#2D362E] dark:text-[#E6DCCF]">
              Denúncia registrada
            </p>
            <p className="text-sm text-muted-foreground mt-1">
              Seu protocolo de acompanhamento é:
            </p>
          </div>
          <div className="flex items-center gap-3">
            <span className="font-mono text-2xl font-bold text-[#57715B] tracking-widest">
              {protocolo}
            </span>
            <button
              type="button"
              data-mia-skip
              onClick={copiarProtocolo}
              className="rounded-xl p-2 hover:bg-[#57715B]/10 text-[#57715B] transition-colors"
              aria-label="Copiar protocolo"
            >
              {copiado ? <CheckCircle className="h-5 w-5 text-emerald-600" /> : <Copy className="h-5 w-5" />}
            </button>
          </div>
        </div>

        {/* Callout de atenção */}
        <div className="rounded-2xl border border-amber-200 dark:border-amber-800/30 bg-amber-50 dark:bg-amber-900/10 p-4 flex gap-3">
          <Shield className="h-5 w-5 text-amber-600 flex-shrink-0 mt-0.5" />
          <div className="text-sm text-amber-700 dark:text-amber-400">
            <p className="font-semibold mb-1">Guarde o protocolo e a senha</p>
            <p>
              Esses dados são a <strong>única forma</strong> de acompanhar sua denúncia.
              Não há recuperação de senha. Recomendamos anotar em local seguro.
            </p>
          </div>
        </div>

        {/* Ação: acompanhar */}
        <Button
          type="button"
          data-mia-skip
          onClick={() => onAcompanhar(protocolo)}
          className="w-full bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-11 gap-2"
        >
          Acompanhar denúncia
          <ChevronRight className="h-4 w-4" />
        </Button>
      </div>
    );
  }

  return (
    <form onSubmit={onSubmit} className="flex flex-col gap-5">
      {/* Callout de anonimato */}
      <div className="rounded-2xl border border-[#57715B]/20 bg-[#57715B]/5 p-4 flex gap-3">
        <Lock className="h-5 w-5 text-[#57715B] flex-shrink-0 mt-0.5" />
        <p className="text-sm text-[#57715B] dark:text-[#8FAE94]">
          Sua identidade é protegida. Não registramos quem você é, seu IP ou se está logado.
          Evite incluir informações que possam te identificar na mensagem.
        </p>
      </div>

      {/* Honeypot — sr-only, nunca visto por humanos */}
      <div className="sr-only" aria-hidden="true">
        <input
          data-mia-skip
          tabIndex={-1}
          autoComplete="off"
          {...register('hp_field')}
        />
      </div>

      {/* Categoria */}
      <div className="flex flex-col gap-1.5">
        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
          Categoria <span className="text-red-500">*</span>
        </Label>
        <Select
          onValueChange={(v) => setValue('categoria', v as CategoriaOuvidoria, { shouldValidate: true })}
        >
          <SelectTrigger data-mia-skip className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl h-11">
            <SelectValue placeholder="Selecione uma categoria" />
          </SelectTrigger>
          <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
            {CATEGORIAS_OUVIDORIA.map((cat) => (
              <SelectItem key={cat.value} value={cat.value}>
                {cat.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {errors.categoria && (
          <p className="text-xs text-red-500">{errors.categoria.message}</p>
        )}
      </div>

      {/* Loja (opcional) */}
      <div className="flex flex-col gap-1.5">
        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
          Loja relacionada <span className="text-muted-foreground font-normal">(opcional)</span>
        </Label>
        <Select onValueChange={(v) => setValue('loja_id', v)}>
          <SelectTrigger data-mia-skip className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl h-11">
            <SelectValue placeholder="Prefiro não informar" />
          </SelectTrigger>
          <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
            <SelectItem value="__nao_informar">Prefiro não informar</SelectItem>
            {LOJAS_OUVIDORIA.map((loja) => (
              <SelectItem key={loja.id} value={String(loja.id)}>
                {loja.nome}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Mensagem */}
      <div className="flex flex-col gap-1.5">
        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
          Mensagem <span className="text-red-500">*</span>
        </Label>
        <textarea
          data-mia-skip
          {...register('mensagem')}
          rows={6}
          maxLength={5000}
          placeholder="Descreva o ocorrido com detalhes..."
          className="w-full resize-none rounded-xl bg-white/60 dark:bg-black/20 backdrop-blur-md border border-[#57715B]/15 px-3 py-2.5 text-sm text-[#2D362E] dark:text-[#E6DCCF] placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#57715B]/30 transition-shadow"
        />
        <div className="flex items-center justify-between">
          {errors.mensagem ? (
            <p className="text-xs text-red-500">{errors.mensagem.message}</p>
          ) : (
            <span />
          )}
          <span className="text-xs text-muted-foreground">
            {mensagemValue.length}/5.000
          </span>
        </div>
      </div>

      {/* Senha de acompanhamento */}
      <div className="flex flex-col gap-1.5">
        <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
          Senha de acompanhamento <span className="text-red-500">*</span>
        </Label>
        <div className="relative">
          <Input
            data-mia-skip
            {...register('senha')}
            type={mostrarSenha ? 'text' : 'password'}
            placeholder="Mínimo 4 caracteres"
            className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl h-11 pr-10"
          />
          <button
            type="button"
            data-mia-skip
            onClick={() => setMostrarSenha((v) => !v)}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-[#57715B] transition-colors"
            aria-label={mostrarSenha ? 'Ocultar senha' : 'Mostrar senha'}
          >
            {mostrarSenha ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
          </button>
        </div>
        <p className="text-xs text-muted-foreground">
          Anote esta senha — ela não pode ser recuperada depois.
        </p>
        {errors.senha && (
          <p className="text-xs text-red-500">{errors.senha.message}</p>
        )}
      </div>

      <Button
        type="submit"
        disabled={enviarDenuncia.isPending}
        className="w-full bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-11 gap-2 mt-1"
      >
        {enviarDenuncia.isPending ? (
          <Loader2 className="h-4 w-4 animate-spin" />
        ) : (
          <Send className="h-4 w-4" />
        )}
        {enviarDenuncia.isPending ? 'Enviando...' : 'Enviar denúncia'}
      </Button>
    </form>
  );
}

// ---------------------------------------------------------------------------
// Sub-componente: Acompanhamento de protocolo
// ---------------------------------------------------------------------------

interface FormAcompanharProps {
  protocoloInicial?: string;
}

function FormAcompanhar({ protocoloInicial }: FormAcompanharProps) {
  const [resultado, setResultado] = useState<ConsultaProtocoloResult | null>(null);
  const [consultaAtual, setConsultaAtual] = useState<{ protocolo: string; senha: string } | null>(null);
  const [respostaTexto, setRespostaTexto] = useState('');
  const [mostrarSenha, setMostrarSenha] = useState(false);

  const consultarProtocolo = useConsultarProtocolo();
  const responderProtocolo = useResponderProtocolo();

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<ConsultaFormValues>({
    resolver: zodResolver(consultaSchema),
    defaultValues: { protocolo: protocoloInicial ?? '' },
  });

  const onConsultar = handleSubmit(async (values) => {
    try {
      const res = await consultarProtocolo.mutateAsync({
        protocolo: values.protocolo.trim().toUpperCase(),
        senha: values.senha,
      });
      setResultado(res);
      if (res.ok) {
        setConsultaAtual({ protocolo: values.protocolo.trim().toUpperCase(), senha: values.senha });
      }
    } catch (err) {
      toast.error((err as Error).message ?? 'Erro ao consultar protocolo');
    }
  });

  const onResponder = async () => {
    if (!consultaAtual || !respostaTexto.trim()) return;
    try {
      await responderProtocolo.mutateAsync({
        protocolo: consultaAtual.protocolo,
        senha: consultaAtual.senha,
        mensagem: respostaTexto.trim(),
      });
      setRespostaTexto('');
      // Reconsultar após resposta
      const res = await consultarProtocolo.mutateAsync(consultaAtual);
      setResultado(res);
      toast.success('Mensagem enviada');
    } catch (err) {
      toast.error((err as Error).message ?? 'Erro ao enviar mensagem');
    }
  };

  return (
    <div className="flex flex-col gap-5">
      {/* Formulário de consulta */}
      <form onSubmit={onConsultar} className="flex flex-col gap-4">
        <div className="flex flex-col gap-1.5">
          <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
            Protocolo
          </Label>
          <Input
            data-mia-skip
            {...register('protocolo')}
            placeholder="Ex.: OUV-20240101-XXXX"
            className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl h-11 font-mono uppercase"
          />
          {errors.protocolo && (
            <p className="text-xs text-red-500">{errors.protocolo.message}</p>
          )}
        </div>

        <div className="flex flex-col gap-1.5">
          <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
            Senha
          </Label>
          <div className="relative">
            <Input
              data-mia-skip
              {...register('senha')}
              type={mostrarSenha ? 'text' : 'password'}
              placeholder="Sua senha de acompanhamento"
              className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl h-11 pr-10"
            />
            <button
              type="button"
              data-mia-skip
              onClick={() => setMostrarSenha((v) => !v)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-[#57715B] transition-colors"
              aria-label={mostrarSenha ? 'Ocultar senha' : 'Mostrar senha'}
            >
              {mostrarSenha ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
            </button>
          </div>
          {errors.senha && (
            <p className="text-xs text-red-500">{errors.senha.message}</p>
          )}
        </div>

        <Button
          type="submit"
          disabled={consultarProtocolo.isPending}
          className="w-full bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-11 gap-2"
        >
          {consultarProtocolo.isPending ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : null}
          {consultarProtocolo.isPending ? 'Consultando...' : 'Consultar protocolo'}
        </Button>
      </form>

      {/* Resultado */}
      {resultado !== null && !resultado.ok && (
        <div className="rounded-2xl border border-red-200 dark:border-red-800/30 bg-red-50 dark:bg-red-900/10 p-4 text-sm text-red-600 dark:text-red-400">
          Protocolo ou senha incorretos.
        </div>
      )}

      {resultado !== null && resultado.ok && (
        <div className="flex flex-col gap-4">
          {/* Cabeçalho da denúncia */}
          <GlassCard className="p-4 flex flex-col gap-3">
            <div className="flex flex-wrap items-center gap-2">
              <span className="font-mono text-sm font-bold text-[#57715B]">
                {resultado.denuncia.protocolo}
              </span>
              <CategoriaBadge categoria={resultado.denuncia.categoria} />
              <StatusBadge status={resultado.denuncia.status} />
            </div>
            <p className="text-xs text-muted-foreground">
              Registrada em{' '}
              {format(parseISO(resultado.denuncia.created_at), "dd/MM/yyyy 'às' HH:mm", {
                locale: ptBR,
              })}
            </p>
            <div className="border-t border-[#57715B]/10 pt-3">
              <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">
                Mensagem original
              </p>
              <p className="text-sm text-[#2D362E] dark:text-[#E6DCCF] whitespace-pre-wrap">
                {resultado.denuncia.mensagem}
              </p>
            </div>
          </GlassCard>

          {/* Thread de mensagens */}
          {resultado.mensagens.length > 0 && (
            <div className="flex flex-col gap-3 py-2">
              <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Conversas
              </p>
              <div className="flex flex-col gap-3">
                {resultado.mensagens.map((msg, i) => (
                  <MensagemBubble key={i} mensagem={msg} />
                ))}
              </div>
            </div>
          )}

          {/* Responder */}
          {resultado.denuncia.status !== 'resolvida' &&
            resultado.denuncia.status !== 'arquivada' && (
              <div className="flex flex-col gap-2">
                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                  Adicionar mensagem
                </p>
                <textarea
                  data-mia-skip
                  value={respostaTexto}
                  onChange={(e) => setRespostaTexto(e.target.value)}
                  rows={3}
                  placeholder="Adicione informações ou acompanhe o andamento..."
                  className="w-full resize-none rounded-xl bg-white/60 dark:bg-black/20 backdrop-blur-md border border-[#57715B]/15 px-3 py-2.5 text-sm text-[#2D362E] dark:text-[#E6DCCF] placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#57715B]/30 transition-shadow"
                />
                <Button
                  type="button"
                  data-mia-skip
                  onClick={onResponder}
                  disabled={!respostaTexto.trim() || responderProtocolo.isPending}
                  className="self-end bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-9 px-4 gap-2 text-sm"
                >
                  {responderProtocolo.isPending ? (
                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
                  ) : (
                    <Send className="h-3.5 w-3.5" />
                  )}
                  Enviar
                </Button>
              </div>
            )}
        </div>
      )}
    </div>
  );
}

