function PainelOuvidoria() {
  const navigate = useNavigate();
  const [filtros, setFiltros] = useState<OuvidoriaFiltros>({});
  const [mostrarFiltros, setMostrarFiltros] = useState(false);

  const { canView } = useOuvidoriaAccess();
  const { data: unread } = useOuvidoriaUnreadCount(canView);
  const { data: denuncias = [], isLoading } = useOuvidoriaList(filtros);

  const totalPorStatus = (status: StatusOuvidoria) =>
    denuncias.filter((d) => d.status === status).length;

  const temFiltros = Boolean(filtros.status || filtros.categoria || filtros.lojaId !== undefined);

  const limparFiltros = () => setFiltros({});

  return (
    <div className="p-4 md:p-6 flex flex-col gap-6 max-w-7xl mx-auto w-full">
      {/* Header */}
      <div className="flex items-center gap-3">
        <div className="rounded-2xl bg-[#57715B]/10 p-3 flex-shrink-0">
          <Shield className="h-6 w-6 text-[#57715B]" />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <h1 className="text-2xl md:text-4xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF]">
              Ouvidoria
            </h1>
            {unread && unread.total > 0 && (
              <span className="inline-flex items-center rounded-full bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800/30 px-2.5 py-0.5 text-xs font-semibold text-amber-600">
                {unread.total} não {unread.total === 1 ? 'lida' : 'lidas'}
              </span>
            )}
          </div>
          <p className="text-xs uppercase tracking-widest text-muted-foreground">
            Canal anônimo de denúncias · acesso restrito
          </p>
        </div>
      </div>

      {/* KPIs */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-4">
        <KpiCard icon={<Inbox />} label="Total" value={denuncias.length} />
        <KpiCard icon={<AlertCircle />} label="Novas" value={totalPorStatus('recebida')} highlight={totalPorStatus('recebida') > 0} />
        <KpiCard icon={<Filter />} label="Em análise" value={totalPorStatus('em_analise')} />
        <KpiCard icon={<CheckCircle2 />} label="Resolvidas" value={totalPorStatus('resolvida')} />
      </div>

      {/* Filtros */}
      <GlassCard className="p-4">
        <div className="flex items-center justify-between mb-3">
          <button
            type="button"
            data-mia-action="ouvidoria-toggle-filtros"
            onClick={() => setMostrarFiltros((v) => !v)}
            className="flex items-center gap-1.5 text-sm font-medium text-[#57715B] hover:text-[#465b49] transition-colors"
          >
            <Filter className="h-4 w-4" />
            Filtros
            {temFiltros && (
              <span className="inline-flex items-center justify-center h-4 w-4 rounded-full bg-[#57715B] text-white text-[10px] font-bold">
                !
              </span>
            )}
          </button>
          {temFiltros && (
            <button
              type="button"
              data-mia-action="ouvidoria-limpar-filtros"
              onClick={limparFiltros}
              className="flex items-center gap-1 text-xs text-muted-foreground hover:text-red-500 transition-colors"
            >
              <X className="h-3.5 w-3.5" />
              Limpar filtros
            </button>
          )}
        </div>

        {mostrarFiltros && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3 pt-2 border-t border-[#57715B]/10">
            {/* Status */}
