              >
                <SelectTrigger data-mia-filter="ouvidoria-status" className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl h-9 text-sm">
                  <SelectValue placeholder="Todos" />
                </SelectTrigger>
                <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
                  <SelectItem value="__todos">Todos os status</SelectItem>
                  {STATUS_OUVIDORIA.map((s) => (
                    <SelectItem key={s.value} value={s.value}>
                      {s.label}
