              <Select
                value={filtros.lojaId !== undefined ? String(filtros.lojaId) : '__todas'}
                onValueChange={(v) =>
                  setFiltros((f) => ({
                    ...f,
                    lojaId: v === '__todas' ? undefined : parseInt(v, 10),
