import React, { type ErrorInfo, type ReactNode } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';
import { AlertTriangle } from 'lucide-react';
import { wideError } from '@/shared/lib/telemetry/wide-events';
import { recordError } from '@/shared/lib/telemetry/metrics';
import { withTraceSync } from '@/shared/lib/telemetry/tracer';

interface TelemetryErrorBoundaryProps {
  moduleName: string;
  fallback?: ReactNode;
  /** Callback adicional chamado quando um erro e capturado (para boundaries especializados) */
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
  children: ReactNode;
}

interface TelemetryErrorBoundaryState {
  hasError: boolean;
}

/**
 * Error Boundary que captura erros de renderizacao React e reporta
 * via telemetria (wide events + metricas + span ERROR) ao Grafana.
 *
 * Uso: envolva rotas ou secoes com moduleName correspondente.
 */
export class TelemetryErrorBoundary extends React.Component<
  TelemetryErrorBoundaryProps,
  TelemetryErrorBoundaryState
> {
  constructor(props: TelemetryErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(): TelemetryErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    const { moduleName, onError } = this.props;
    const route = typeof window !== 'undefined' ? window.location.pathname : '';

    // Span ERROR via OTel tracer
    try {
      withTraceSync(
        `react.error_boundary.${moduleName}`,
        (span) => {
          if (span) {
            span.setAttribute('module', moduleName);
            span.setAttribute('error.name', error.name);
            span.setAttribute('error.message', error.message);
            span.setAttribute('page.route', route);
            span.setStatus({ code: 2, message: error.message }); // ERROR
            span.recordException(error);
          }
        },
        { module: moduleName, 'error.type': 'react_error_boundary' },
      );
    } catch {
      // Telemetria pode nao estar inicializada — nao propagar
    }

    wideError('react.error_boundary', error.message, {
      domain: moduleName,
      attributes: {
        module: moduleName,
        'error.name': error.name,
        'error.message': error.message,
        'error.stack': (error.stack ?? '').slice(0, 500),
        'error.component_stack': (errorInfo.componentStack ?? '').slice(0, 500),
        'page.route': route,
      },
    });

    recordError('react_error_boundary', moduleName);

    onError?.(error, errorInfo);
  }

  handleRetry = (): void => {
    this.setState({ hasError: false });
  };

  render(): ReactNode {
    if (this.state.hasError) {
      if (this.props.fallback) {
        return this.props.fallback;
      }

      return (
        <Card className="m-4 border-destructive">
          <CardHeader className="flex flex-row items-center gap-3">
            <AlertTriangle className="h-6 w-6 text-destructive" />
            <CardTitle className="text-lg text-destructive">
              Algo deu errado neste módulo
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="mb-4 text-sm text-muted-foreground">
              Ocorreu um erro inesperado no módulo{' '}
              <strong>{this.props.moduleName}</strong>. Tente novamente ou
              recarregue a página.
            </p>
            <div className="flex gap-2">
              <Button variant="outline" onClick={this.handleRetry}>
                Tentar novamente
              </Button>
              <Button
                variant="ghost"
                onClick={() => window.location.reload()}
              >
                Recarregar página
              </Button>
            </div>
          </CardContent>
        </Card>
      );
    }

    return this.props.children;
  }
}

